//images.unsplash.com/photo-1591857177580-dc82b9ac4e1e?crop=entropy&cs=srgb&fm=jpg&q=85&w=1200",vm="https://images.pexels.com/photos/1301856/pexels-photo-1301856.jpeg?auto=compress&cs=tinysrgb&dpr=2&h=900&w=1200",ym="https://images.pexels.com/photos/2382904/pexels-photo-2382904.jpeg?auto=compress&cs=tinysrgb&dpr=2&h=900&w=1200",bm="https://images.pexels.com/photos/2933243/pexels-photo-2933243.jpeg?auto=compress&cs=tinysrgb&dpr=2&h=900&w=1200",xm="https://images.pexels.com/photos/3825527/pexels-photo-3825527.jpeg?auto=compress&cs=tinysrgb&dpr=2&h=900&w=1200",wm="./images/career/career-lab.jpg",km="6285283790848",Sm=[{value:2008,suffix:"",key:"founded",noFormat:!0},{value:120,suffix:"+",key:"isolates"},{value:16,suffix:"+",key:"provinces"},{value:15e3,suffix:"+",key:"farmers"}],Cm=[{slug:"bio-fertilizers",targetUrl:"/solutions?type=Bio%20Fertilizer,Bio%20Stimulant%20%26%20Nutrition",title:{en:"Bio Fertilizers & Biostimulant",id:"Bio Fertilizers & Biostimulant"},desc:{en:"Live microbes that fix nitrogen, solubilize phosphate and trigger a plant's own defenses \u2014 a stronger foundation from the roots up.",id:"Mikroba hidup yang mengikat nitrogen, melarutkan fosfat, dan memicu pertahanan alami tanaman \u2014 fondasi lebih kuat dari akar."},image:"/images/solution-bio-fertilizer.jpg",accent:"#43B14B"},{slug:"bio-crop-protection",targetUrl:"/solutions?type=Bio%20Insecticide,Bio%20Fungicide",title:{en:"Bio Crop Protection",id:"Bio Crop Protection"},desc:{en:"Insect-specific fungi and bacteria that control pests and disease through targeted infection \u2014 sparing pollinators and beneficials.",id:"Jamur dan bakteri spesifik yang mengendalikan hama dan penyakit lewat infeksi tertarget \u2014 aman bagi penyerbuk dan serangga bermanfaat."},image:"/images/solution-bio-protection.jpg",accent:"#2D6A35"},{slug:"soil-remediation",targetUrl:"/solutions?type=Bio%20Decomposer",title:{en:"Bio Decomposer",id:"Bio Decomposer"},desc:{en:"Bio-decomposers that turn crop residue and plantation waste into usable soil \u2014 a practical alternative to open burning.",id:"Bio-decomposer yang mengubah sisa panen dan limbah perkebunan menjadi tanah subur \u2014 alternatif praktis pembakaran terbuka."},image:"/images/bio-decomposer.jpg",accent:"#E8A500"}],Em=["Bio Fertilizer","Bio Insecticide","Bio Fungicide","Bio Stimulant & Nutrition","Bio Decomposer"],jm={"bio-fertilizers":{type:"Bio Fertilizer",title:"Bio Fertilizers",image:mm,desc:{en:"Our bio-fertilizers work through the roots, building healthier plants from the ground up. Each formulation carries live microbes that fix nitrogen, solubilize phosphate or trigger a plant's own natural defenses, giving crops a stronger foundation without relying on synthetic inputs alone.",id:"Pupuk hayati kami bekerja melalui akar, membangun tanaman lebih sehat dari dasar. Setiap formulasi membawa mikroba hidup yang mengikat nitrogen, melarutkan fosfat, atau memicu pertahanan alami tanaman."}},"bio-fungicides":{type:"Bio Fungicide",title:"Bio Fungicides",image:bm,desc:{en:"Our bio-fungicides use living organisms, not synthetic chemicals, to suppress the fungal and bacterial diseases that threaten yield. Each product is built around microbes proven to compete with, infect or block the pathogens they target, from root rot to fruit rot to blast disease.",id:"Bio-fungisida kami memakai organisme hidup, bukan bahan kimia sintetis, untuk menekan penyakit jamur dan bakteri yang mengancam hasil panen."}},"bio-insecticides":{type:"Bio Insecticide",title:"Bio Insecticides",image:ym,desc:{en:"Our bio-insecticides control pests the way nature does, through targeted infection rather than broad spectrum poison. Each formulation is built around insect-specific fungi or bacteria that leave pollinators and natural predators alone, so the rest of the ecosystem around your crop keeps working for you.",id:"Bio-insektisida kami mengendalikan hama seperti cara alam, lewat infeksi tertarget bukan racun spektrum luas \u2014 membiarkan penyerbuk dan predator alami tetap bekerja."}},"soil-remediation":{type:"Bio Decomposer",title:"Bio Decomposer",image:vm,desc:{en:"Our bio-decomposers turn crop residue, plantation waste and manure into usable soil far faster than nature would on its own, while rebuilding the biological activity that healthy soil depends on. From rice straw to oil palm empty bunches, these products shorten the wait between harvest and healthy ground.",id:"Bio-decomposer kami mengubah sisa panen, limbah perkebunan, dan kotoran menjadi tanah subur jauh lebih cepat, sekaligus memulihkan aktivitas biologis tanah."}},"biostimulant-nutrition":{type:"Bio Stimulant & Nutrition",title:"Bio Stimulant & Nutrition",image:fm,desc:{en:"Our bio-stimulant and nutrition products fill the gaps that fertilizer alone cannot reach, from micronutrients and amino acids to natural plant hormones and soil conditioners. Each one is built to support a specific stage of growth, whether that is stronger roots early on or fuller grain and fruit at the finish.",id:"Produk bio-stimulan dan nutrisi kami mengisi celah yang tak terjangkau pupuk saja \u2014 dari mikronutrien dan asam amino hingga hormon tanaman alami dan pembenah tanah."}}},Pm=["Paddy","Corn","Chilli","Tomato","Potato","Shallot","Oil Palm","Sugarcane","Banana","Durian","Cacao","Citrus"],Nm={"Bio Fertilizer":{slug:"bio-fertilizers",image:mm,form:[["Active organism","Beneficial bacteria consortium"],["Concentration","\u2265 1 \xd7 10\u2078 CFU/g"],["Formulation type","Carrier-based powder"],["Shelf life","24 months (ANHYDRIOM\u2122)"]],app:[["General use","2 kg/ha","Soil / seed","At planting / land prep"]]},"Bio Insecticide":{slug:"bio-insecticides",image:ym,form:[["Active organism","Entomopathogenic microbe"],["Concentration","\u2265 1 \xd7 10\u2079 CFU/g"],["Formulation type","Wettable powder (WP)"],["Shelf life","36 months (ANHYDRIOM\u2122)"]],app:[["General use","1\u20132 kg/ha or 5 g/L","Foliar / soil","At pest onset, repeat 10\u201314 days"]]},"Bio Fungicide":{slug:"bio-fungicides",image:bm,form:[["Active organism","Antagonist microbe(s)"],["Concentration","\u2265 1 \xd7 10\u2079 CFU/g"],["Formulation type","Wettable powder (WP)"],["Shelf life","24 months (ANHYDRIOM\u2122)"]],app:[["General use","5 g/L water","Foliar & drench","Preventive, every 10\u201314 days"]]},"Bio Stimulant & Nutrition":{slug:"biostimulant-nutrition",image:fm,form:[["Active content","Humic / amino / mineral complex"],["Source","Natural extract"],["Formulation type","Soluble powder / liquid"],["Shelf life","36 months"]],app:[["General use","2\u20133 g/L or per label","Foliar / fertigation","Per growth stage"]]},"Bio Decomposer":{slug:"soil-remediation",image:vm,form:[["Active organism","Cellulolytic & lignolytic consortium"],["Concentration","\u2265 1 \xd7 10\u2079 CFU/g"],["Formulation type","Powder"],["Shelf life","24 months"]],app:[["Crop residue","1\u20132 kg/tonne","Spray & incorporate","Post-harvest"]]}},Tm=e=>e.toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/^-+|-+$/g,""),Am=e=>"Rice"===e?"Paddy":e,Fm=[{name:"SEUDOFLOR",type:"Bio Fungicide",activeOrganism:"Pseudomonas fluorescens",regNo:"RI.01060120258873",cardCrops:["Banana","Chilli","Tomato"],crops:["Banana","Chilli","Tomato","Potato","Melon"],image:"/images/products/seudoflor.jpg",keyBenefit:{en:"Formulated as a soil protector & root activator for horticultural crops, preventing sudden wilting and Pythium infection.",id:"Diformulasikan sebagai pelindung akar & aktivator tanah untuk tanaman hortikultura, mencegah layu mendadak dan serangan Pythium."},benefits:{en:["Helps prevent plants from wilting suddenly during cultivation","Supports seedling protection against Pythium infection from the start of planting","Activates beneficial microbes in the plant root zone","Helps support phosphate availability for optimal root development","Formulated as a soil protector & root activator for horticultural crops"],id:["Membantu tanaman tidak mudah layu mendadak saat budidaya","Melindungi bibit dari serangan Pythium sejak awal tanam","Mengaktifkan mikroba baik di zona perakaran tanaman","Membantu ketersediaan fosfat untuk perakaran yang optimal","Diformulasikan sebagai pelindung akar & aktivator tanah untuk tanaman hortikultura"]},what:{en:"SEUDOFLOR is formulated with Pseudomonas fluorescens to protect root zones against sudden wilt and early Pythium damping-off while mobilizing bound phosphate for vigorous root establishment.",id:"SEUDOFLOR diformulasikan dengan Pseudomonas fluorescens untuk melindungi zona perakaran dari layu mendadak dan infeksi Pythium sejak awal tanam, sekaligus melarutkan fosfat untuk pertumbuhan akar yang optimal."},formulation:[["Active organism","Pseudomonas fluorescens"],["Concentration","\u2265 1 \xd7 10\u2078 CFU/g"],["Formulation type","Wettable powder (WP)"],["Shelf life","24 months (ANHYDRIOM\u2122)"]],application:[["Chilli / Tomato","2.5\u20135 g/L water","Root drench / spray","At planting & every 10\u201314 days"],["Potato / Melon","2\u20135 kg/ha","Soil application","Pre-planting soil treatment"]]},{name:"PAENAMAXI",type:"Bio Fungicide",activeOrganism:"Paenibacillus polymyxa + Bacillus amyloliquefaciens",regNo:"RI.01020120227340",cardCrops:["Shallot","Paddy","Cucumber"],crops:["Shallot","Paddy","Cucumber","Melon","Watermelon"],image:"/images/products/paenamaxi.jpg",keyBenefit:{en:"Contains bioactive compounds that help control Rice Blast, Bacterial Leaf Blight, and shallot Purple Spot.",id:"Mengandung senyawa bioaktif untuk membantu mengendalikan Blas, Hawar Daun Bakteri pada padi, dan Bercak Ungu bawang merah."},benefits:{en:["Developed to help control Rice Blast and Bacterial Leaf Blight in rice","Helps control Purple Spot/Alternaria Leaf Spot in shallot","Supports control of Powdery Mildew and Downy Mildew","Helps manage Coffee Leaf Rust; preventive application is recommended","Contains Paenibacillus polymyxa and Bacillus amyloliquefaciens, which produce bioactive compounds that inhibit fungal and bacterial pathogens"],id:["Dikembangkan untuk membantu mengendalikan Blas dan Hawar Daun Bakteri pada padi","Membantu mengendalikan Bercak Ungu/Alternaria pada bawang merah","Mendukung pengendalian Embun Tepung dan Embun Bulu","Membantu mengatasi Karat Daun pada tanaman kopi; aplikasi preventif disarankan","Mengandung Paenibacillus polymyxa dan Bacillus amyloliquefaciens yang menghasilkan senyawa bioaktif penghambat patogen jamur dan bakteri"]},what:{en:"PAENAMAXI uses a dual-strain bacterial biofungicide (Paenibacillus polymyxa and Bacillus amyloliquefaciens) to produce bioactive secondary metabolites that inhibit both fungal and bacterial leaf and panicle diseases.",id:"PAENAMAXI menggunakan biofungisida bakteri ganda (Paenibacillus polymyxa dan Bacillus amyloliquefaciens) yang menghasilkan metabolit sekunder bioaktif untuk menghambat patogen jamur dan bakteri pada daun dan malai."},formulation:[["Active organism","Paenibacillus polymyxa + Bacillus amyloliquefaciens"],["Concentration","\u2265 1 \xd7 10\u2078 CFU/g"],["Formulation type","Wettable powder (WP)"],["Shelf life","24 months (ANHYDRIOM\u2122)"]],application:[["Paddy","2.5\u20135 g/L water","Foliar spray","At tillering and booting stage"],["Shallot","2.5\u20135 g/L water","Foliar spray","Every 7\u201310 days preventive"]]},{name:"BIOTRACOL",type:"Bio Fungicide",activeOrganism:"Trichoderma asperellum + Bacillus subtilis",regNo:"RI.01020120186156",cardCrops:["Banana","Chilli","Cacao"],crops:["Banana","Chilli","Tomato","Potato","Cacao","Avocado","Cabbage","Citrus","Durian"],image:"/images/products/biotracol.jpg",keyBenefit:{en:"Contains active microorganisms that help suppress symptoms of Phytophthora (fruit rot, root rot) and Sigatoka disease.",id:"Mengandung mikroba aktif penghambat patogen untuk menekan gejala penyakit Phytophthora dan Sigatoka."},benefits:{en:["Contains active microorganisms that help inhibit plant pathogens","Helps suppress symptoms of Phytophthora (fruit rot, root rot) and Sigatoka disease","Environmentally friendly, leaves no harmful residue","Supports healthy, productive chili, cocoa, and banana crops with regular, proper application"],id:["Mengandung mikroba aktif penghambat patogen","Menekan gejala penyakit Phytoptora dan Sigatoka","Ramah lingkungan dan tidak meninggalkan residu","Mendukung kondisi tanaman cabai, kakao, dan pisang tetap sehat dan produktif dengan aplikasi yang tepat dan teratur"]},what:{en:"BIOTRACOL combines active antagonist microorganisms that colonize crop surfaces to outcompete and suppress Phytophthora fruit/root rot and Sigatoka disease, leaving zero chemical residue.",id:"BIOTRACOL menggabungkan mikroorganisme antagonis aktif yang mengoloni permukaan tanaman untuk menekan penyakit busuk Phytophthora dan Sigatoka tanpa meninggalkan residu kimia berbahaya."},formulation:[["Active organism","Trichoderma asperellum + Bacillus subtilis"],["Concentration","\u2265 1 \xd7 10\u2079 CFU/g"],["Formulation type","Wettable powder (WP)"],["Shelf life","24 months (ANHYDRIOM\u2122)"]],application:[["Banana","5 g/L water","Foliar & drench","Every 10\u201314 days"],["Durian","10 g/L water","Soil drench","Monthly"],["Cacao","5 g/L water","Foliar spray","Every 14 days"]]},{name:"MOLERIMAX",type:"Bio Fungicide",activeOrganism:"Acremonium variecolor",regNo:"RI.01020120258841",cardCrops:["Shallot"],crops:["Shallot"],image:"/images/products/molerimax.jpg",keyBenefit:{en:"Developed specifically to help control Fusarium Wilt (Moler disease) in shallot using endophytic Acremonium variecolor.",id:"Dikembangkan khusus untuk membantu mengendalikan penyakit Layu Fusarium (Moler) pada bawang merah dengan cendawan endofit."},benefits:{en:["Developed specifically to help control Fusarium Wilt (Moler disease) in shallot","Contains an endophytic fungus (Acremonium variecolor) that enters plant tissue to help defend against Fusarium oxysporum","Works by boosting the plant's own defensive exudates against the pathogen","Soluble powder formulation, easy to apply mixed with fe